const locationBlock=()=>`<section class="section location"><div><span class="eyebrow">Seu próximo momento de cuidado</span><h2>Esperamos por você<br>em Itapeva.</h2><p>R. Érico Pímentel Dias, 187 · 1º andar<br>Jardim Ophelia, Itapeva — SP<br>CEP 18400-465</p><p><a href="tel:+5515997771757">(15) 99777-1757 ↗</a></p><p class="muted">Consulte os horários de atendimento diretamente com a equipe.</p><a class="btn light" href="https://www.google.com/maps/place/Beautique+Est%C3%A9tica+e+Hair+-+Itapeva+sp/@-23.9845137,-48.8799546,17z/data=!3m1!4b1!4m6!3m5!1s0x94c38d839dc605ed:0x5c22880ecc68b37b!8m2!3d-23.9845137!4d-48.8799546!16s%2Fg%2F11x7kxfvqj" target="_blank" rel="noopener">Como chegar ↗</a></div><iframe title="Localização da Beautique em Itapeva" loading="lazy" referrerpolicy="no-referrer" src="https://maps.google.com/maps?q=R.%20%C3%89rico%20P%C3%ADmentel%20Dias%2C%20187%2C%20Itapeva%20SP&output=embed"></iframe></section>`;
const gallery=()=>`<div class="gallery">${['hero','facial','spa','hair','manicure'].map(k=>`<button class="gallery-item" data-image="${photo(k,1400)}" data-alt="${k==='manicure'?'Trabalho de unhas publicado no perfil da Beautique':'Ambiente real da Beautique Estética & Hair em Itapeva'}" aria-label="${k==='manicure'?'Ampliar foto de unhas':'Ampliar foto do espaço da Beautique'}"><img src="${photo(k,700)}" alt="${k==='manicure'?'Trabalho de unhas publicado no perfil da Beautique no Google Maps':'Ambiente real da Beautique Estética & Hair em Itapeva'}" loading="lazy" width="700" height="600"></button>`).join('')}</div><p class="caption">Fotos reais do espaço e um registro de trabalho de unhas publicados no <a href="https://www.google.com/maps/place/Beautique+Est%C3%A9tica+e+Hair+-+Itapeva+sp/@-23.9845137,-48.8799546,17z/data=!3m1!4b1!4m6!3m5!1s0x94c38d839dc605ed:0x5c22880ecc68b37b!8m2!3d-23.9845137!4d-48.8799546!16s%2Fg%2F11x7kxfvqj" target="_blank" rel="noopener">perfil da empresa no Google Maps</a>. Consulte a equipe para confirmar os serviços disponíveis atualmente.</p>`;
const intro=()=>`<section class="section intro"><div><img src="${photo('facial')}" alt="Espaço de atendimento da Beautique Estética & Hair" loading="lazy" width="900" height="1000"><p class="caption">Foto real do espaço da Beautique · Google Maps.</p></div><div><span class="eyebrow">A essência Beautique</span><h2>Mais do que beleza,<br>uma experiência.</h2><p class="muted">Um espaço em Itapeva dedicado à beleza, ao cuidado e ao bem-estar. Da estética aos cuidados com os cabelos, cada momento é um convite para olhar para você com carinho.</p><p class="muted">Clientes destacam a equipe profissional, o atendimento atencioso e o ambiente acolhedor nas avaliações públicas do Google.</p><a class="btn light" href="/sobre/">Conheça a Beautique ↗</a></div></section>`;
if(!path){main.innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">Estética & Hair · Itapeva, SP</span><h1>Beleza, cuidado<br>e bem-estar em<br><em>cada detalhe.</em></h1><p>Um espaço dedicado a proporcionar momentos de cuidado, beleza e autoestima. O seu tempo de se sentir bem começa aqui.</p><div class="actions"><a class="btn" href="/agendar/">Solicitar atendimento ↗</a><a class="btn light" href="/servicos/">Conhecer serviços</a></div><a class="eyebrow" href="#essencia">Explore a Beautique ↓</a></div><div class="hero-photo"><img src="${photo('hero',1600)}" alt="Recepção real da Beautique Estética & Hair em Itapeva" fetchpriority="high" width="1600" height="1700"><span class="photo-label">BEM-VINDA À BEAUTIQUE · ITAPEVA, SP</span></div></section><div class="strip"><span>Beleza que acolhe</span><span>Cuidado em cada detalhe</span><span>O seu momento, do seu jeito</span></div><div id="essencia">${intro()}</div><section class="section"><div class="section-top"><div><span class="eyebrow">Nossos cuidados</span><h2>Um cuidado especial<br>para cada momento.</h2></div><a href="/servicos/" class="btn light">Explore os serviços ↗</a></div><div class="cards">${cards(cats.slice(0,3))}</div><p class="caption">Fotos reais do espaço. Estética facial e corporal, hair, spa e Dia da Noiva. Consulte procedimentos, valores e disponibilidade.</p></section><section class="editorial"><div><span class="eyebrow">Spa & bem-estar</span><h2>Permita-se viver<br>um momento<br><em>só seu.</em></h2><p class="muted">Dê espaço a uma pausa. Conheça a proposta de bem-estar da Beautique e converse com a equipe sobre as experiências disponíveis.</p><a class="btn light" href="/spa/">Descubra o seu momento ↗</a></div><div><img src="${photo('spa')}" loading="lazy" alt="Ambiente real da Beautique Estética & Hair" width="1100" height="900"><p class="caption">Foto real do espaço da Beautique · Google Maps.</p></div></section><section class="reputation"><span class="eyebrow">Confiança que inspira</span><h2>A confiança de quem já<br>viveu essa experiência.</h2><div class="stars" aria-label="Nota de referência no Google">★★★★★</div><div class="rating">4,9<span style="font-size:24px"> / 5</span></div><div class="review-quotes"><p class="muted" style="color:#daccc2">“Amo esse lugar, as meninas são muito profissionais. Atendimento maravilhoso.”</p><p class="muted" style="color:#daccc2">“Profissionais atenciosos, ambiente acolhedor e muito cuidado em cada detalhe.”</p><p class="muted" style="color:#daccc2">“Muito bom, a clínica é linda, as meninas são umas queridas.”</p></div><p class="muted" style="color:#daccc2">87 avaliações no Google · consulta em 14/10/2026. A nota pode mudar.</p><a class="btn" style="border-color:#c6ad99" href="https://www.google.com/maps/place/Beautique+Est%C3%A9tica+e+Hair+-+Itapeva+sp/@-23.9845137,-48.8799546,17z/data=!3m1!4b1!4m6!3m5!1s0x94c38d839dc605ed:0x5c22880ecc68b37b!8m2!3d-23.9845137!4d-48.8799546!16s%2Fg%2F11x7kxfvqj" target="_blank" rel="noopener">Ler avaliações no Google ↗</a></section><section class="section"><div class="section-top"><div><span class="eyebrow">Dia da Noiva</span><h2>Cada detalhe do seu grande<br>dia merece ser especial.</h2></div><a class="btn light" href="/dia-da-noiva/">Vamos planejar juntas ↗</a></div></section>${locationBlock()}`;}
else if(path==='sobre')main.innerHTML=title('Conheça a Beautique','Um espaço para<br>cuidar de você.')+intro()+`<section class="editorial"><div><h2>O seu momento<br>começa aqui.</h2><p>Beleza, autoestima e bem-estar se encontram em uma proposta de cuidado que valoriza cada pessoa. Converse com a equipe para conhecer os serviços e escolher a experiência mais adequada para você.</p><a class="btn" href="/contato/">Fale com a equipe ↗</a></div><div><img src="${photo('hero')}" alt="Salão em imagem ilustrativa" loading="lazy"><p class="caption">Foto real do espaço da Beautique · Google Maps.</p></div></section>`;
else if(path==='servicos')main.innerHTML=title('Nossos cuidados','Beleza em todas<br>as suas formas.','Explore os segmentos divulgados pela Beautique. A equipe informa os procedimentos, valores e profissionais disponíveis.')+`<section class="section" style="padding-top:20px"><div class="filters"><input id="search" type="search" placeholder="Buscar um cuidado" aria-label="Pesquisar categoria" style="max-width:350px"><select id="category" aria-label="Filtrar segmento" style="max-width:250px"><option value="">Todos os segmentos</option>${cats.map(c=>`<option value="${c.slug}">${c.name}</option>`).join('')}</select></div><div id="catalog" class="cards">${cards()}</div><p class="caption">Fotos reais do espaço da Beautique. Consulte valores diretamente com a equipe.</p></section>`;
else if(path.startsWith('servicos/')){const c=cats.find(c=>path===`servicos/${c.slug}`);main.innerHTML=c?title('Nossos cuidados',c.name,c.description)+`<section class="editorial"><div><img src="${photo(c.image)}" alt="Ambiente da Beautique Estética & Hair"><p class="caption">Foto real do espaço da Beautique · Google Maps.</p></div><div><h2>Um cuidado pensado<br>para você.</h2><p>Converse com a equipe para conhecer os procedimentos disponíveis neste segmento, a indicação de cada cuidado e as orientações necessárias.</p><p>Valores: <strong>mediante consulta</strong></p><p class="muted">Duração, profissionais e disponibilidade são informados pela equipe antes da confirmação.</p><a class="btn" href="/agendar/?categoria=${c.slug}">Consultar agendamento ↗</a></div></section>`:title('Serviços','Categoria não encontrada.');}
else if(path==='spa')main.innerHTML=title('Spa & bem-estar','Permita-se viver um<br>momento só seu.','Uma pausa para respirar, desacelerar e colocar o seu bem-estar em primeiro lugar.')+`<section class="editorial"><div><img src="${photo('spa')}" alt="Inspiração de spa, fotografia ilustrativa"><p class="caption">Foto real do espaço da Beautique · Google Maps.</p></div><div><h2>O tempo de cuidar<br>de você.</h2><p>Conheça as experiências de bem-estar disponíveis na Beautique. Serviços, duração e composição de pacotes são informados pela equipe.</p><a class="btn" href="/agendar/?categoria=spa-bem-estar">Consultar experiências ↗</a></div></section>`;
else if(path==='galeria')main.innerHTML=title('Inspirações','Beleza que se sente<br>em cada detalhe.','Conheça os ambientes reais da Beautique Estética & Hair em Itapeva.')+`<section class="section" style="padding-top:20px">${gallery()}</section>`;
else if(path==='contato')main.innerHTML=title('Estamos por aqui','Vamos conversar?','Conheça os cuidados disponíveis ou tire suas dúvidas diretamente com a equipe.')+locationBlock()+`<section class="section" style="padding-top:0"><a class="btn light" href="https://www.instagram.com/beautique.esteticaehair/" target="_blank" rel="noopener">Acompanhe no Instagram ↗</a></section>`;
const contactForm=(bridal)=>`<section class="section" style="padding-top:20px"><form id="contact-form" class="form"><h3>${bridal?'Conte sobre o seu grande dia.':'O seu cuidado começa aqui.'}</h3><p class="muted">Esta é uma solicitação de contato. Data e horário desejados dependem de confirmação da equipe.</p><label>Nome *<input name="name" required maxlength="120" autocomplete="name"></label><div class="form-grid"><label>Telefone *<input name="phone" type="tel" required pattern="[0-9+\\u0028\\u0029\\s\\u002D]{10,20}" autocomplete="tel" maxlength="20"></label><label>${bridal?'Data do evento':'Data desejada (opcional)'}<input name="date" type="date" ${bridal?'required':''} min="${new Date().toLocaleDateString('en-CA')}"></label></div><label>Segmento de interesse<select name="category">${cats.map(c=>`<option value="${c.name}" ${new URLSearchParams(location.search).get('categoria')===c.slug?'selected':''}>${c.name}</option>`).join('')}</select></label>${bridal?'<label>Quantidade de participantes (opcional)<input name="participants" type="number" min="1" max="1000"></label>':'<label>Horário de preferência (opcional)<input name="time" type="time"></label><label>E-mail (opcional)<input name="email" type="email" autocomplete="email" maxlength="200"></label>'}<label>Observações (opcional)<textarea name="notes" rows="3" maxlength="1000" placeholder="Não inclua informações de saúde ou outros dados sensíveis."></textarea></label><label><input type="checkbox" name="consent" required> Autorizo o uso destes dados para responder à minha solicitação e li a <a href="/privacidade/" style="text-decoration:underline">Política de Privacidade</a>.</label><button type="submit">Preparar solicitação →</button><p class="status" id="form-status" role="status" aria-live="polite"></p><div id="request-result"></div></form></section>`;
if(path==='agendar')main.innerHTML=title('Agendamento','Vamos conversar<br>sobre o seu cuidado.','Conte o que você procura. A equipe orienta sobre serviços, profissionais e disponibilidade.')+contactForm(false);
if(path==='dia-da-noiva')main.innerHTML=title('Dia da Noiva','O seu grande dia.<br>O seu momento.','Cada detalhe merece atenção. Converse com a equipe sobre serviços e experiências para a sua celebração.')+`<section class="editorial"><div><img src="${photo('bride')}" alt="Ambiente real da Beautique Estética & Hair"><p class="caption">Foto real do espaço da Beautique · Google Maps.</p></div><div><h2>Uma experiência<br>com a sua essência.</h2><p>Compartilhe a data e o que imagina para esse momento. A equipe pode orientar sobre os cuidados disponíveis e preparar um orçamento de acordo com a sua solicitação.</p><a href="#contact-form" class="btn light">Solicitar orçamento ↓</a></div></section>`+contactForm(true);
if(path==='privacidade')main.innerHTML=title('Seus dados','Política de Privacidade')+`<article class="prose"><p>Este site apresenta a Beautique Estética & Hair e permite preparar solicitações de atendimento. Contato: (15) 99777-1757, Rua Érico Pimentel Dias, 187, 1º andar, Jardim Ophelia, Itapeva — SP.</p><h2>Informações fornecidas</h2><p>Os formulários solicitam nome, telefone, segmento de interesse e, quando pertinente, data do evento. E-mail e observações são opcionais. Os dados são utilizados para responder à solicitação e tratar o pedido de atendimento.</p><h2>Como funciona o envio</h2><p>Sem uma integração de envio ativa, o formulário prepara uma mensagem para você copiar e compartilhar com a equipe. Nesse modo, o site não grava os dados em uma agenda. Se um sistema de recebimento for ativado, uma confirmação será mostrada somente após o registro bem-sucedido.</p><h2>Serviços externos</h2><p>As fotografias desta versão são imagens do perfil público da Beautique no Google Maps. As fontes podem ser carregadas do Google Fonts e o mapa do Google pode receber informações técnicas, como seu endereço IP. Links para Instagram e ferramentas de contato abrem plataformas com suas próprias políticas.</p><h2>Seus direitos e escolhas</h2><p>Para solicitar informações sobre seus dados, correção, eliminação ou revogar uma autorização, entre em contato com o estabelecimento pelo telefone informado. Evite incluir dados de saúde ou outras informações sensíveis no campo de observações.</p><h2>Cookies e retenção</h2><p>Não há analytics ou publicidade instalados nesta versão. A sessão administrativa é usada apenas durante o acesso autenticado. A política de retenção para uma futura agenda precisa ser definida pela empresa antes da ativação.</p><p class="muted">Versão de 14 de outubro de 2026. Esta política deverá ser revisada pelo estabelecimento antes da disponibilização pública e da ativação da coleta persistente.</p></article>`;
if(path==='termos')main.innerHTML=title('Informações de uso','Termos de Uso')+`<article class="prose"><h2>Atendimento e informações</h2><p>As informações deste site são institucionais. Procedimentos, duração, valores, profissionais, horários e eventuais pacotes devem ser consultados diretamente com a Beautique.</p><h2>Solicitações</h2><p>Preparar ou enviar uma solicitação não confirma agendamento, orçamento ou disponibilidade. A confirmação depende do atendimento da equipe.</p><h2>Imagens e reputação</h2><p>As imagens mostram ambientes reais da Beautique, obtidas do perfil público da empresa no Google Maps. A nota e as avaliações exibidas são uma referência consultada em 14/10/2026 e não são atualizadas automaticamente.</p><h2>Uso responsável</h2><p>Não envie dados de terceiros sem autorização. As informações não substituem orientação individual de profissionais responsáveis.</p><p class="muted">Versão de 14/10/2026. Texto sujeito à revisão e aprovação do estabelecimento.</p></article>`;
document.querySelector('#menu').addEventListener('click',e=>{const open=document.querySelector('#nav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open));});
document.querySelectorAll('nav a').forEach(a=>{if(a.pathname===location.pathname)a.setAttribute('aria-current','page');});
if(document.querySelector('#search')){const filter=()=>{const q=document.querySelector('#search').value.toLocaleLowerCase('pt-BR'),cat=document.querySelector('#category').value;const found=cats.filter(c=>(!cat||c.slug===cat)&&c.name.toLocaleLowerCase('pt-BR').includes(q));document.querySelector('#catalog').innerHTML=found.length?cards(found):'<p role="status">Nenhum segmento encontrado. Tente outra busca.</p>';};document.querySelector('#search').oninput=filter;document.querySelector('#category').onchange=filter;}
let imageIndex=0;const galleryItems=[...document.querySelectorAll('.gallery-item')],dialog=document.querySelector('#lightbox');function showImage(i){imageIndex=(i+galleryItems.length)%galleryItems.length;const image=document.querySelector('#lightimage');image.src=galleryItems[imageIndex].dataset.image;image.alt=galleryItems[imageIndex].dataset.alt;}
galleryItems.forEach((el,i)=>el.onclick=()=>{showImage(i);dialog.showModal();});document.querySelector('#close').onclick=()=>dialog.close();document.querySelector('#prev').onclick=()=>showImage(imageIndex-1);document.querySelector('#next').onclick=()=>showImage(imageIndex+1);dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft')showImage(imageIndex-1);if(e.key==='ArrowRight')showImage(imageIndex+1);});
const form=document.querySelector('#contact-form');if(form)form.onsubmit=async e=>{e.preventDefault();if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form)),message=`Olá! Gostaria de ${path==='dia-da-noiva'?'solicitar um orçamento para Dia da Noiva':'consultar um agendamento'} na Beautique Estética & Hair.\nNome: ${values.name}\nTelefone: ${values.phone}\nSegmento: ${values.category}\nData desejada: ${values.date||'A combinar'}\n${values.time?'Horário de preferência: '+values.time+'\n':''}${values.participants?'Participantes: '+values.participants+'\n':''}${values.email?'E-mail: '+values.email+'\n':''}${values.notes?'Observações: '+values.notes:''}\nAguardo confirmação de disponibilidade.`;const result=document.querySelector('#request-result');result.replaceChildren();const text=document.createElement('textarea');text.rows=8;text.readOnly=true;text.value=message;text.setAttribute('aria-label','Mensagem de solicitação');result.append(text);const copy=document.createElement('button');copy.type='button';copy.textContent='Copiar mensagem';copy.onclick=async()=>{try{await navigator.clipboard.writeText(message);document.querySelector('#form-status').textContent='Mensagem copiada. Compartilhe com a equipe para solicitar atendimento.';}catch{text.select();document.querySelector('#form-status').textContent='Selecione a mensagem e copie para compartilhar.';}};result.append(copy);if(config.whatsappConfirmed){const a=document.createElement('a');a.href='https://wa.me/5515997771757?text='+encodeURIComponent(message);a.className='btn';a.target='_blank';a.rel='noopener';a.textContent='Abrir WhatsApp';result.append(a);}else{const a=document.createElement('a');a.href='tel:+5515997771757';a.className='btn light';a.textContent='Ligar para a equipe';result.append(a);}document.querySelector('#form-status').textContent='Mensagem preparada. Ela ainda não foi enviada e nenhum horário foi reservado.';};
// Supabase Auth + REST. Public key is safe only with the migration RLS policies enabled.
let accessToken=null;
async function api(table,method='GET',body=null,query=''){const r=await fetch(`${config.supabaseUrl}/rest/v1/${table}${query}`,{method,headers:{apikey:config.supabaseAnonKey,...(accessToken?{Authorization:`Bearer ${accessToken}`}:(config.supabaseAnonKey.split('.').length===3?{Authorization:`Bearer ${config.supabaseAnonKey}`} : {})),'Content-Type':'application/json',Prefer:'return=representation'},body:body?JSON.stringify(body):undefined});if(!r.ok)throw new Error('Não foi possível concluir a operação. Verifique sua permissão e conexão.');return r.status===204?[]:r.json();}
function adminLogin(){main.innerHTML=title('Gestão Beautique','Área administrativa','Acesso restrito aos administradores autorizados.')+`<section class="section" style="padding-top:0">${!config.supabaseUrl||!config.supabaseAnonKey?'<div class="notice">O acesso administrativo será disponibilizado após a configuração segura do sistema de gestão.</div>':'<form id="login" class="form"><label>E-mail<input name="email" type="email" required autocomplete="username"></label><label>Senha<input name="password" type="password" required autocomplete="current-password"></label><button>Entrar</button><p role="status" class="status"></p></form>'}</section>`;const f=document.querySelector('#login');if(f)f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button');b.disabled=true;try{const r=await fetch(config.supabaseUrl+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:config.supabaseAnonKey,'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(f)))});if(!r.ok)throw new Error('Acesso não autorizado. Confira suas credenciais.');const data=await r.json();accessToken=data.access_token;const profile=await api('profiles','GET',null,'?select=role&id=eq.'+data.user.id);if(profile[0]?.role!=='admin'){accessToken=null;throw new Error('Conta sem permissão administrativa.');}await loadAdmin();}catch(error){f.querySelector('.status').textContent=error.message;}finally{b.disabled=false;}};}
if(path==='admin')adminLogin();
if(!path){const ld=document.createElement('script');ld.type='application/ld+json';ld.textContent=JSON.stringify({'@context':'https://schema.org','@type':'BeautySalon',name:'Beautique Estética & Hair',telephone:'+5515997771757',address:{'@type':'PostalAddress',streetAddress:'R. Érico Pímentel Dias, 187, 1º andar, Jardim Ophelia',addressLocality:'Itapeva',addressRegion:'SP',postalCode:'18400-465',addressCountry:'BR'},sameAs:['https://www.instagram.com/beautique.esteticaehair/']});document.head.append(ld);}
// Render only actual configured services when a Supabase catalog is connected.
if(path==='servicos'&&config.supabaseUrl&&config.supabaseAnonKey){(async()=>{const area=document.querySelector('#catalog');try{const services=await api('services','GET',null,'?select=id,slug,name,description,category_slug,price_cents,duration_minutes&active=eq.true&order=name');const render=()=>{const q=document.querySelector('#search').value.toLocaleLowerCase('pt-BR'),category=document.querySelector('#category').value;const found=services.filter(s=>(!category||s.category_slug===category)&&s.name.toLocaleLowerCase('pt-BR').includes(q));area.replaceChildren();if(!found.length){area.innerHTML='<p role="status">Nenhum procedimento disponível para esta busca. Consulte a equipe.</p>';return;}found.forEach(s=>{const article=document.createElement('article');article.className='card';const h=document.createElement('h3');h.textContent=s.name;const p=document.createElement('p');p.textContent=s.description||'Consulte a equipe para mais informações.';const info=document.createElement('p');info.textContent=(s.price_cents===null?'Consultar valores':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(s.price_cents/100))+(s.duration_minutes?' · '+s.duration_minutes+' min':'');const link=document.createElement('a');link.href='/agendar/?categoria='+encodeURIComponent(s.category_slug);link.className='btn light';link.textContent='Consultar agendamento ↗';article.append(h,p,info,link);area.append(article);});};render();document.querySelector('#search').oninput=render;document.querySelector('#category').onchange=render;}catch(e){area.innerHTML='<p role="alert">Não foi possível carregar os procedimentos. <a href="/contato/">Fale com a equipe</a>.</p>';}})();}
// Complete record editors; all writes continue to use server-enforced RLS.
const adminLabels={services:'Serviços',professionals:'Profissionais',professional_services:'Vínculos de serviços',professional_availability:'Jornadas',availability_exceptions:'Bloqueios e ausências',appointments:'Agenda',gallery_items:'Galeria autorizada',testimonials:'Depoimentos',site_settings:'Configurações',content_sections:'Textos e seções',bridal_inquiries:'Orçamentos de noivas'};
const fieldSets={services:{name:'Nome',slug:'URL curta',category_slug:'Categoria',description:'Descrição',duration_minutes:'Duração em minutos',price_cents:'Preço em centavos',photo_url:'URL de fotografia',active:'Ativo'},professionals:{name:'Nome',description:'Descrição autorizada',photo_url:'URL de fotografia',active:'Ativo'},professional_services:{professional_id:'UUID do profissional',service_id:'UUID do serviço'},professional_availability:{professional_id:'UUID do profissional',weekday:'Dia da semana (0 domingo a 6 sábado)',starts_at:'Início da jornada',ends_at:'Fim da jornada'},availability_exceptions:{professional_id:'UUID do profissional',starts_at:'Início do bloqueio',ends_at:'Fim do bloqueio',reason:'Motivo'},gallery_items:{photo_url:'URL de fotografia',alt:'Descrição da imagem',authorized:'Uso autorizado'},testimonials:{public_name:'Nome público',quote:'Depoimento real autorizado',source_url:'URL da fonte',stars:'Estrelas (1–5)',authorized:'Uso autorizado'},site_settings:{key:'Chave da configuração',value:'Valor JSON'},content_sections:{slug:'Seção',content:'Conteúdo JSON'}};
const numericFields=['duration_minutes','price_cents','weekday','stars'];
async function loadAdmin(){main.innerHTML=title('Gestão Beautique','Painel administrativo')+`<section class="section" style="padding-top:0"><div class="admin-layout"><aside class="admin-nav">${Object.entries(adminLabels).map(([key,name])=>`<button data-tab="${key}">${name}</button>`).join('')}<button id="logout">Sair</button></aside><div id="admin-content" aria-live="polite"></div></div></section>`;document.querySelector('#logout').onclick=async()=>{try{await fetch(config.supabaseUrl+'/auth/v1/logout',{method:'POST',headers:{apikey:config.supabaseAnonKey,Authorization:`Bearer ${accessToken}`}});}finally{accessToken=null;adminLogin();}};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>adminTab(b.dataset.tab));await adminTab('services');}
async function adminTab(table){const area=document.querySelector('#admin-content');area.innerHTML='<p role="status">Carregando registros…</p>';try{const rows=await api(table,'GET',null,'?select=*');area.replaceChildren();const heading=document.createElement('h3');heading.textContent=adminLabels[table];area.append(heading);const summary=document.createElement('p');summary.textContent=rows.length+' registro(s) reais.';area.append(summary);const status=document.createElement('p');status.className='status';status.setAttribute('role','status');area.append(status);
const showEditor=(row={})=>{document.querySelector('#record-editor')?.remove();const editor=document.createElement('form');editor.id='record-editor';editor.className='form';const heading=document.createElement('h3');heading.textContent=row.id?'Editar registro':'Novo registro';editor.append(heading);Object.entries(fieldSets[table]).forEach(([key,label])=>{const l=document.createElement('label');l.textContent=label;let input;if(['description','quote','value','content'].includes(key)){input=document.createElement('textarea');input.rows=4;}else input=document.createElement('input');input.name=key;if(['active','authorized'].includes(key)){input.type='checkbox';input.checked=row[key]??key==='active';}else if(numericFields.includes(key)){input.type='number';input.value=row[key]??'';if(['duration_minutes','stars'].includes(key))input.min=1;else input.min=0;if(key==='weekday')input.max=6;if(key==='stars')input.max=5;}else if(['starts_at','ends_at'].includes(key)){input.type=table==='professional_availability'?'time':'datetime-local';input.value=table==='professional_availability'?(row[key]||''):(row[key]?new Date(new Date(row[key]).getTime()-new Date(row[key]).getTimezoneOffset()*60000).toISOString().slice(0,16):'');}else{input.value=typeof row[key]==='object'&&row[key]!==null?JSON.stringify(row[key],null,2):(row[key]??'');if(key.endsWith('_url'))input.type='url';input.maxLength=key==='description'?2000:5000;}if(['name','slug','key','professional_id','service_id','photo_url','alt','public_name','quote','source_url','starts_at','ends_at'].includes(key))input.required=true;l.append(input);editor.append(l);});const save=document.createElement('button');save.textContent='Salvar';const cancel=document.createElement('button');cancel.textContent='Fechar editor';cancel.type='button';cancel.onclick=()=>editor.remove();editor.append(save,cancel);editor.onsubmit=async e=>{e.preventDefault();if(!editor.reportValidity())return;save.disabled=true;try{const v={};Object.keys(fieldSets[table]).forEach(key=>{const input=editor.elements.namedItem(key);if(input.type==='checkbox')v[key]=input.checked;else if(numericFields.includes(key))v[key]=input.value===''?null:Number(input.value);else if(['value','content'].includes(key))v[key]=JSON.parse(input.value);else if(['starts_at','ends_at'].includes(key)&&table==='availability_exceptions')v[key]=new Date(input.value).toISOString();else v[key]=input.value||null;});await api(table,row.id||table==='professional_services'&&row.professional_id?'PATCH':'POST',v,row.id?'?id=eq.'+row.id:row.professional_id?'?professional_id=eq.'+row.professional_id+'&service_id=eq.'+row.service_id:'');await adminTab(table);}catch(e){status.textContent=e instanceof SyntaxError?'Informe um valor JSON válido.':e.message;save.disabled=false;}};area.append(editor);editor.scrollIntoView({block:'center',behavior:'smooth'});};
if(fieldSets[table]){const add=document.createElement('button');add.textContent='Criar novo registro';add.onclick=()=>showEditor();area.append(add);}if(table==='appointments'){const b=document.createElement('button');b.textContent='Criar reserva na agenda';b.onclick=()=>reservationEditor(area,status);area.append(b);const label=document.createElement('label');label.textContent='Filtrar agenda por data';const date=document.createElement('input');date.type='date';date.onchange=()=>{[...area.querySelectorAll('tbody tr')].forEach(tr=>tr.hidden=!!date.value&&tr.dataset.date!==date.value);};label.append(date);area.append(label);}
const wrap=document.createElement('div');wrap.className='table-wrap';const t=document.createElement('table');t.innerHTML='<thead><tr><th>Registro / identificador</th><th>Detalhes</th><th>Ações</th></tr></thead>';const body=document.createElement('tbody');rows.forEach(row=>{const tr=document.createElement('tr');if(row.starts_at)tr.dataset.date=new Date(row.starts_at).toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'});const name=document.createElement('td');name.textContent=(row.name||row.public_name||row.customer_name||row.key||row.slug||row.professional_id||row.id)+'\n'+(row.id||'');name.style.whiteSpace='pre-line';const detail=document.createElement('td');detail.textContent=row.starts_at?new Date(row.starts_at).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'})+(row.status?' · '+row.status:''):row.description||row.alt||(row.active===false?'Inativo':row.authorized===false?'Não autorizado':'');const actions=document.createElement('td');if(fieldSets[table]){const edit=document.createElement('button');edit.textContent='Editar';edit.onclick=()=>showEditor(row);actions.append(edit);}if(table==='appointments'){const select=document.createElement('select');select.setAttribute('aria-label','Status do agendamento');['pending','confirmed','cancelled','completed'].forEach(key=>{const o=document.createElement('option');o.value=key;o.textContent=({pending:'Pendente',confirmed:'Confirmado',cancelled:'Cancelado',completed:'Concluído'})[key];o.selected=row.status===key;select.append(o);});select.onchange=async()=>{try{await api(table,'PATCH',{status:select.value},'?id=eq.'+row.id);await adminTab(table);}catch(e){status.textContent=e.message;select.value=row.status;}};actions.append(select);const reschedule=document.createElement('button');reschedule.textContent='Remarcar';reschedule.onclick=()=>rescheduleEditor(area,status,row);actions.append(reschedule);}if(fieldSets[table]){const del=document.createElement('button');del.textContent='Excluir';del.onclick=()=>{if(!confirm('Excluir este registro permanentemente?'))return;(async()=>{try{await api(table,'DELETE',null,row.id?'?id=eq.'+row.id:'?professional_id=eq.'+row.professional_id+'&service_id=eq.'+row.service_id);await adminTab(table);}catch(e){status.textContent=e.message;}})();};actions.append(del);}tr.append(name,detail,actions);body.append(tr);});t.append(body);wrap.append(t);area.append(wrap);if(!rows.length){const empty=document.createElement('p');empty.className='empty';empty.textContent='Nenhum registro cadastrado.';area.append(empty);}}catch(e){area.innerHTML='<p role="alert">'+escapeHtml(e.message)+'</p>';}}
async function reservationEditor(area,status){document.querySelector('#record-editor')?.remove();try{const [services,professionals]=await Promise.all([api('services'),api('professionals')]);const f=document.createElement('form');f.className='form';f.id='record-editor';f.innerHTML='<h3>Nova reserva</h3><p>A disponibilidade é validada no banco antes de registrar.</p>';[['p_service','Serviço',services],['p_professional','Profissional',professionals]].forEach(([key,label,rows])=>{const l=document.createElement('label');l.textContent=label;const select=document.createElement('select');select.name=key;select.required=true;rows.forEach(row=>{const o=document.createElement('option');o.value=row.id;o.textContent=row.name;select.append(o);});l.append(select);f.append(l);});[['p_start','Data e horário de Itapeva (UTC−3)','datetime-local'],['p_name','Nome da cliente','text'],['p_phone','Telefone','tel'],['p_email','E-mail opcional','email'],['p_notes','Observações opcionais','text']].forEach(([key,label,type])=>{const l=document.createElement('label');l.textContent=label;const input=document.createElement('input');input.name=key;input.type=type;input.required=!['p_email','p_notes'].includes(key);l.append(input);f.append(l);});const consent=document.createElement('label');consent.innerHTML='<input type="checkbox" required> A cliente autorizou o tratamento dos dados para esta reserva.';const b=document.createElement('button');b.textContent='Registrar reserva pendente';f.append(consent,b);f.onsubmit=async e=>{e.preventDefault();b.disabled=true;try{const v=Object.fromEntries(new FormData(f));v.p_start=new Date(v.p_start+'-03:00').toISOString();v.p_email=v.p_email||null;v.p_notes=v.p_notes||null;const protocol=await api('rpc/reserve_appointment','POST',v);await adminTab('appointments');const p=document.createElement('p');p.setAttribute('role','status');p.textContent='Reserva pendente registrada. Protocolo: '+protocol;document.querySelector('#admin-content').append(p);}catch(e){status.textContent=e.message;b.disabled=false;}};area.append(f);}catch(e){status.textContent=e.message;}}
function rescheduleEditor(area,status,row){document.querySelector('#record-editor')?.remove();const f=document.createElement('form');f.className='form';f.id='record-editor';f.innerHTML='<h3>Remarcar agendamento</h3><label>Nova data e horário de Itapeva (UTC−3)<input name="p_start" type="datetime-local" required></label><button>Salvar remarcação</button>';f.onsubmit=async e=>{e.preventDefault();try{await api('rpc/reschedule_appointment','POST',{p_id:row.id,p_start:new Date(f.elements.p_start.value+'-03:00').toISOString()});await adminTab('appointments');}catch(e){status.textContent=e.message;}};area.append(f);}
// Editorial text is managed independently of client records.
if(config.supabaseUrl&&config.supabaseAnonKey){(async()=>{try{const sections=await api('content_sections','GET',null,'?select=slug,content');const record=sections.find(s=>s.slug===(path||'home'));if(record?.content){if(typeof record.content.title==='string'){const h=main.querySelector('h1');if(h)h.textContent=record.content.title;}if(typeof record.content.description==='string'){const p=main.querySelector('.hero-copy p,.page-title p');if(p)p.textContent=record.content.description;}}
if(path==='galeria'){const records=await api('gallery_items','GET',null,'?select=photo_url,alt&authorized=eq.true');if(records.length){const grid=document.querySelector('.gallery');grid.replaceChildren();records.forEach(row=>{if(!/^https:\/\//.test(row.photo_url))return;const b=document.createElement('button');b.className='gallery-item';const img=document.createElement('img');img.src=row.photo_url;img.alt=row.alt;img.loading='lazy';b.append(img);b.onclick=()=>{document.querySelector('#lightimage').src=row.photo_url;document.querySelector('#lightimage').alt=row.alt;dialog.showModal();document.querySelector('#lightbox .caption').textContent=row.alt;};grid.append(b);});document.querySelector('.gallery + .caption').textContent='Fotografias autorizadas pela equipe.';document.querySelector('#prev').hidden=true;document.querySelector('#next').hidden=true;}}}catch{/* Static institutional content remains available during a connection failure. */}})();}
